exec(open(__file__.replace('repair-more.py','repair.py')).read().split("step('lem-cm-lattice")[0])
replace('lem-tame-transport-commutator',r'$a\in\ell^1,a\in\ell^2$',r'$a\in\ell^1,b\in\ell^2$')
replace('lem-tame-transport-commutator',r'$H^m$ is a real Hilbert space with $\langle f,g\rangle=\sum_k\widehat f(k)\cdot\overline{\widehat g(k)}$',r'$H^m$ is a real Hilbert space with weighted inner product $\langle f,g\rangle_{H^m}=\sum_kw_k^{2m}\widehat f(k)\cdot\overline{\widehat g(k)}$, while the unweighted pairing $\langle f,g\rangle$ used in the statement is the $L^2$ pairing')
step('lem-tame-transport-commutator','1.2',r'**Weight comparison.** Extend $w$ to $\mathbb R^3$ by $w(x)=(1+4\pi^2|x|_2^2)^{1/2}$. Its gradient has norm at most $2\pi$, and $w(l+tv)\le w(l)+2\pi|v|_2\le w_l+w_v$ for $0\le t\le1$. Since here $m>5/2$, the convexity inequality $(a+b)^{m-1}\le2^{m-2}(a^{m-1}+b^{m-1})$ applies. Integrating the derivative of $w(l+tv)^m$ for $v=k-l$ gives $|w_k^m-w_l^m|\le m2\pi2^{m-2}|v|_2(w_v^{m-1}+w_l^{m-1})$. [given, algebra]')
step('lem-tame-transport-commutator','2.1',r'**Meaning and coefficients of the commutator.** Put $u_N=P_Nu$, the Fourier truncation, which converges to $u$ in $H^m$ and $H^s$ by [F4]. For polynomials the commutator has coefficients $c_k=\sum_l(w_k^m-w_l^m)(\widehat u(k-l)\cdot2\pi il)\widehat u(l)$ by finite convolution. The same series for general $u$ is absolutely convergent: the bounds of step 3.1 below apply also to the sum of absolute values, and each convolution of an $\ell^2$ family with an $\ell^1$ family is finite at each coordinate by [F2]. The two terms in the displayed commutator need not separately lie in $L^2$. They are interpreted in $H^{-1}$: the first lies there because $(u\cdot\nabla)u\in H^{m-1}$ by the transport product bound [F2], and the second is $\sum_j\partial_j(u_j\Lambda^mu)$ since $\operatorname{div}u=0$. Here $u_j$ is bounded by [F5], $\Lambda^mu\in L^2$, and differentiation maps $L^2$ to $H^{-1}$ coefficientwise because $2\pi|k_j|/w_k\le1$. Products and these derivatives are defined by limits of the truncated fields; $u_N\to u$ uniformly and $\Lambda^mu_N\to\Lambda^mu$ in $L^2$, so the limits exist and agree with the stated products. Thus the difference is well defined in $H^{-1}$ and its coefficients are the series just displayed. [step 1.2, F1, F2, F3, F4, F5]')
step('lem-tame-transport-commutator','3.1',r'For $v=k-l$ define $P_v:=|v|_2w_v^{m-1}|\widehat u(v)|_2$, $Q_l:=2\pi|l|_2|\widehat u(l)|_2$, $A_v:=|v|_2|\widehat u(v)|_2$ and $B_l:=2\pi|l|_2w_l^{m-1}|\widehat u(l)|_2$. Step 1.2 bounds $|c_k|$ by $m2\pi2^{m-2}[(P*Q)(k)+(A*B)(k)]$. Since $2\pi|k|_2\le w_k$, $\|P\|_2\le(2\pi)^{-1}\|u\|_{H^m}$ and $\|B\|_2\le\|u\|_{H^m}$; [F1] gives $\|Q\|_1\le W\prime_s\|u\|_{H^s}$ and $\|A\|_1\le(2\pi)^{-1}W\prime_s\|u\|_{H^s}$. Young [F2] therefore gives $\|c\|_2\le m2^{m-1}W\prime_s\|u\|_{H^m}\|u\|_{H^s}\le C_m\|u\|_{H^m}\|u\|_{H^s}$ with the unchanged $C_m=4\pi^2m2^{m-2}(W\prime_s+1)$. The same calculation for the bilinear coefficient expression with different inputs $a,b$ bounds it by $m2^{m-2}W\prime_s(\|a\|_{H^m}\|b\|_{H^s}+\|a\|_{H^s}\|b\|_{H^m})$. Applying this to $u_N-u$ and $u_N,u$ shows convergence of the truncated commutators in $\ell^2$. Parseval [F3] supplies their $L^2$ limit, which is the $H^{-1}$ difference of step 2.1. This proves claim 2 without strengthening its $H^m$ hypothesis. [step 1.2, step 2.1, F1, F2, F3, F4]')
replace('lem-tame-transport-commutator',r'W\prime_s',r"W'_s")
replace('lem-fluid-galerkin-coefficient-ivp',r'$P_N$ is the orthogonal projection of $H^s$ onto $X_N$',r'$P_N$ restricted to the real divergence-free subspace $H^s_\sigma$ is the orthogonal projection onto $X_N$')
replace('lem-fluid-galerkin-coefficient-ivp',r'Suppose $\|u_N(t)\|_{H^s}\le R$ for $t$ near $T_{\max}$ and let $t_j\uparrow T_{\max}$',r'If the asserted norm divergence fails, there are $R<\infty$ and times $t_j\uparrow T_{\max}$ with $\|u_N(t_j)\|_{H^s}\le R$')
replace('lem-fluid-energy-common-lifespan',r'(with $Y_\epsilon(0)\to Y_0$ and $Y_\epsilon(t)\to Y(t)$)',r'(with $Y_\epsilon(0)\to\|P_Nu_0\|_{H^s}\le Y_0$ and $Y_\epsilon(t)\to Y(t)$; the function $y\mapsto y/(1-C_syt)$ is increasing while its denominator is positive)')
replace('lem-fourier-tail-diagonal-compact-convergence','3. $u(t)$ is real and divergence-free for every $t$,','3. $u(t)$ is real for every $t$ and is divergence-free whenever every $u_N(t)$ is divergence-free,')
replace('lem-fourier-tail-diagonal-compact-convergence','Realness and the divergence-free condition are coefficientwise linear conditions preserved under limits by [F5]','Realness is preserved under limits by [F5]; if the approximants are divergence-free, their equations $k\cdot\widehat{u_N}(k,t)=0$ pass to the limit as well')
step('lem-fourier-tail-diagonal-compact-convergence','1.1',r'Enumerate the countable set of pairs $(k,q)$, $k\in\mathbb Z^3$, $q\in D$, using [F4]. Each real coordinate sequence of $\widehat{u_N}(k,q)$ is bounded by (b). A bounded real sequence has a deterministically specified convergent subsequence: start with the integer $M\ge1$ least such that every value lies in $[-M,M]$; repeatedly bisect the current closed interval and retain the left half if it contains infinitely many terms, otherwise the right half. At each stage select the least later index whose value belongs to the retained interval. The resulting subsequence is Cauchy because the interval lengths tend to zero, hence converges. Apply this specified rule successively to the six real coordinates of each vector and to each enumerated pair, nesting the infinite index sets. The diagonal index $N_j$ is the least member of the $j$th retained index set larger than $N_{j-1}$. For every fixed pair its tail is a subsequence of the corresponding retained sequence and hence converges. This supplies convergence on each finite frequency block at every dyadic time; no dependent selection principle is used. [F1, F4]')
replace('thm-local-smooth-periodic-euler-viscous-solution','[F1] For each $N$','[F1] For each integer $N\ge1$')
replace('thm-local-smooth-periodic-euler-viscous-solution',r'$\|(P_N-P)z\|_{H^r}\le(2\pi(N+1))^{-1}\|z\|_{H^{r+1}}$',r'$\|(P_N-I)z\|_{H^r}\le(2\pi(N+1))^{-1}\|z\|_{H^{r+1}}$; equivalently this bound holds with $P_N-P$ when $z=Pz$')
replace('thm-local-smooth-periodic-euler-viscous-solution',r'3C_{m-1}B_{m-1}^2',r'3C_{m-1}B_{m-1}B_m')
replace('def-holomorphic-kam-domain-and-diophantine-labels','for a nonempty set $\Omega\subseteq\mathbb R^n$','for a set $\Omega\subseteq\mathbb R^n$')
replace('def-holomorphic-kam-domain-and-diophantine-labels','The **action-angle neighbourhood** of width',r'For $\Omega=\varnothing$ the infimum is taken in the extended nonnegative reals with $\inf\varnothing=+\infty$, so $O_h(\varnothing)=\varnothing$ for every finite $h\ge0$. Supremum norms of functions on an empty domain are $0$ (the supremum in $[0,+\infty]$). Thus an empty Diophantine label set gives an empty parameter family; results quantified over its labels are vacuous, and positive-measure assertions require their separately stated hypotheses.'+'\n\n'+'The **action-angle neighbourhood** of width')
